// ============================================
// 6. MORSI — Nati dalla Bocca
// Buchi irregolari nel nero (come morsi) che rivelano
// l'immagine sotto. Forme più organiche/strappate.
// ============================================
const MorsiAnim = ({ army, field, onComplete, isSkippable }) => {
  const { phase, skip } = useAnim(onComplete, isSkippable, [30, 950, 1150]);

  const bites = useMemo(() =>
    Array.from({ length: 14 }).map(() => ({
      x: 5 + Math.random() * 90,
      y: 5 + Math.random() * 90,
      r: 22 + Math.random() * 20,
      delay: Math.random() * 0.25,
      subs: Array.from({ length: 4 }).map(() => ({
        dx: (Math.random() - 0.5) * 18,
        dy: (Math.random() - 0.5) * 18,
        dr: 12 + Math.random() * 14,
      })),
    })), []
  );

  return (
    <div className="absolute inset-0 overflow-hidden cursor-pointer" onClick={skip}>
      {/* Immagine sotto */}
      <div className="absolute inset-0">
        <Img src={army.image} />
      </div>

      {/* Nero sopra con morsi SVG */}
      <div className="absolute inset-0 pointer-events-none" style={{
        opacity: phase >= 2 ? 0 : 1,
        transition: 'opacity 200ms',
        zIndex: 5,
      }}>
        <svg width="100%" height="100%" style={{ display: 'block' }}>
          <defs>
            <mask id="bitesMask">
              <rect width="100%" height="100%" fill="white" />
              {bites.map((b, i) => (
                <g key={i}>
                  <circle
                    cx={`${b.x}%`} cy={`${b.y}%`}
                    r={phase >= 1 ? `${b.r}%` : '0%'}
                    fill="black"
                    style={{ transition: `r 600ms cubic-bezier(0.16, 1, 0.3, 1) ${b.delay}s` }}
                  />
                  {b.subs.map((s, j) => (
                    <circle key={j}
                      cx={`${b.x + s.dx}%`} cy={`${b.y + s.dy}%`}
                      r={phase >= 1 ? `${s.dr}%` : '0%'}
                      fill="black"
                      style={{ transition: `r 600ms cubic-bezier(0.16, 1, 0.3, 1) ${b.delay + 0.05}s` }}
                    />
                  ))}
                </g>
              ))}
            </mask>
          </defs>
          <rect width="100%" height="100%" fill="black" mask="url(#bitesMask)" />
        </svg>
      </div>

      <Overlay field={field} army={army} visible={phase >= 1} />
    </div>
  );
};

// ============================================
// 7. SCAGLIE — Enclave delle Scaglie
// Occhio rettile che si apre: due palpebre
// si separano rivelando l'immagine attraverso
// una pupilla verticale che si allarga
// ============================================
const ScaglieAnim = ({ army, field, onComplete, isSkippable }) => {
  const [phase, setPhase] = useState(0);
  const [skipped, setSkipped] = useState(false);

  useEffect(() => {
    if (skipped) { setPhase(2); onComplete?.(); return; }
    const t = [
      setTimeout(() => setPhase(1), 30),
      setTimeout(() => setPhase(2), 1200),
      setTimeout(() => onComplete?.(), 1900),
    ];
    return () => t.forEach(clearTimeout);
  }, [skipped]);

  const skip = () => { if (isSkippable) setSkipped(true); };

  // Palpebra: ellisse orizzontale che si apre
  // Fase 0: chiuso (ellisse piattissima)
  // Fase 1: aperto (ellisse ampia)
  const eyeH = phase >= 1 ? 85 : 0; // altezza apertura in %

  return (
    <div className="absolute inset-0 overflow-hidden cursor-pointer" onClick={skip}>
      {/* Immagine sotto */}
      <div className="absolute inset-0">
        <Img src={army.image} />
      </div>

      {/* Palpebra superiore — con bordo sfumato */}
      <div className="absolute pointer-events-none" style={{
        left: 0, right: 0, top: 0,
        height: `${50 - eyeH / 2 + 8}%`,
        background: 'linear-gradient(to bottom, black 70%, transparent 100%)',
        opacity: phase >= 2 ? 0 : 1,
        transition: 'height 1100ms cubic-bezier(0.16, 1, 0.3, 1), opacity 600ms ease-out',
        zIndex: 5,
      }} />

      {/* Palpebra inferiore — con bordo sfumato */}
      <div className="absolute pointer-events-none" style={{
        left: 0, right: 0, bottom: 0,
        height: `${50 - eyeH / 2 + 8}%`,
        background: 'linear-gradient(to top, black 70%, transparent 100%)',
        opacity: phase >= 2 ? 0 : 1,
        transition: 'height 1100ms cubic-bezier(0.16, 1, 0.3, 1), opacity 600ms ease-out',
        zIndex: 5,
      }} />

      {/* Bordo sottile dorato lungo il taglio dell'occhio */}
      <div className="absolute left-0 right-0 pointer-events-none" style={{
        top: `${50 - eyeH / 2}%`,
        height: '2px',
        background: `linear-gradient(90deg, transparent 10%, ${army.accent}40, transparent 90%)`,
        transition: 'top 1100ms cubic-bezier(0.16, 1, 0.3, 1)',
        opacity: phase >= 2 ? 0 : 0.6,
        transitionProperty: 'top, opacity',
        transitionDuration: '1100ms, 400ms',
        zIndex: 6,
      }} />
      <div className="absolute left-0 right-0 pointer-events-none" style={{
        top: `${50 + eyeH / 2}%`,
        height: '2px',
        background: `linear-gradient(90deg, transparent 10%, ${army.accent}40, transparent 90%)`,
        transition: 'top 1100ms cubic-bezier(0.16, 1, 0.3, 1)',
        opacity: phase >= 2 ? 0 : 0.6,
        transitionProperty: 'top, opacity',
        transitionDuration: '1100ms, 400ms',
        zIndex: 6,
      }} />

      <Overlay field={field} army={army} visible={phase >= 1} />
    </div>
  );
};

// ============================================
// 8. CADUTA — Ratti della Megera
// Wipe dall'alto al basso: lento in cima,
// accelera scendendo
// ============================================
const CadutaAnim = ({ army, field, onComplete, isSkippable }) => {
  const [phase, setPhase] = useState(0);
  const [skipped, setSkipped] = useState(false);
  const [revealY, setRevealY] = useState(0);

  useEffect(() => {
    if (skipped) { setPhase(2); onComplete?.(); return; }
    const timers = [
      setTimeout(() => setPhase(1), 30),
      setTimeout(() => setPhase(2), 1100),
      setTimeout(() => onComplete?.(), 1300),
    ];

    // Ease-in: lento all'inizio, veloce alla fine
    let start = null;
    let raf;
    const animate = (ts) => {
      if (!start) start = ts;
      const elapsed = ts - start;
      const duration = 1000;
      const t = Math.min(elapsed / duration, 1);
      // Ease-in cubico: lento in cima, accelera in basso
      const eased = t * t * t;
      setRevealY(eased * 100);
      if (t < 1) raf = requestAnimationFrame(animate);
    };
    const animStart = setTimeout(() => { raf = requestAnimationFrame(animate); }, 50);

    return () => { timers.forEach(clearTimeout); clearTimeout(animStart); cancelAnimationFrame(raf); };
  }, [skipped]);

  const skip = () => { if (isSkippable) setSkipped(true); };

  return (
    <div className="absolute inset-0 overflow-hidden cursor-pointer" onClick={skip}>
      <div className="absolute inset-0 bg-black" />

      {/* Immagine rivelata dall'alto */}
      <div className="absolute inset-0" style={{
        clipPath: `inset(0 0 ${100 - revealY}% 0)`,
      }}>
        <Img src={army.image} />
      </div>

      {/* Bordo sottile verdastro sul fronte */}
      <div className="absolute left-0 right-0 pointer-events-none" style={{
        top: `${revealY}%`,
        height: '1px',
        background: `linear-gradient(90deg, transparent, ${army.accent}60, transparent)`,
        boxShadow: `0 0 6px ${army.accent}40`,
        opacity: phase >= 2 ? 0 : 0.5,
        transition: 'opacity 200ms',
        zIndex: 10,
      }} />

      <Overlay field={field} army={army} visible={phase >= 1} />
    </div>
  );
};

