const ANIM_MAP = {
  swirl: SwirlAnim,
  frammenti: FrammentiAnim,
  sipario: SiparioAnim,
  hud: HudAnim,
  onda: OndaAnim,
  morsi: MorsiAnim,
  scaglie: ScaglieAnim,
  caduta: CadutaAnim,
};

export default function App() {
  const [armyIdx, setArmyIdx] = useState(0);
  const [fieldIdx, setFieldIdx] = useState(0);
  const [animating, setAnimating] = useState(false);
  const [revealed, setRevealed] = useState(false);
  const [animKey, setAnimKey] = useState(0);
  const [skippable, setSkippable] = useState(true);

  const trigger = useCallback((aIdx, fIdx) => {
    setRevealed(false);
    setAnimating(true);
    if (aIdx !== undefined) setArmyIdx(aIdx);
    if (fIdx !== undefined) setFieldIdx(fIdx);
    setAnimKey(k => k + 1);
  }, []);

  const onComplete = () => { setAnimating(false); setRevealed(true); };
  const army = ARMIES[armyIdx];
  const field = SAMPLE_FIELDS[fieldIdx];
  const Anim = ANIM_MAP[army.animId];

  return (
    <div className="h-screen bg-slate-950 text-white flex flex-col overflow-hidden select-none">
      <div className="bg-black/60 border-b border-slate-800/50 px-5 py-2 flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-3">
          <span className="text-amber-400 font-black text-sm tracking-wider">⚔️ SATZE</span>
          <span className="text-slate-600 text-xs">Animazioni v5</span>
        </div>
        <label className="flex items-center gap-2 text-xs text-slate-500 cursor-pointer">
          <input type="checkbox" checked={skippable} onChange={e => setSkippable(e.target.checked)} className="accent-amber-400" />
          Skippabile
        </label>
      </div>

      <div className="flex-1 flex min-h-0">
        <div className="w-52 border-r border-slate-800/40 p-2 flex flex-col gap-0.5 flex-shrink-0 overflow-y-auto">
          <div className="text-[10px] text-slate-600 uppercase tracking-widest mb-1 px-2 font-bold">Armata</div>
          {ARMIES.map((a, i) => (
            <button key={a.id}
              onClick={() => { setArmyIdx(i); trigger(i, fieldIdx); }}
              className={`w-full text-left px-2.5 py-1.5 rounded-lg text-xs transition-all ${
                armyIdx === i ? 'text-white font-bold' : 'text-slate-500 hover:bg-slate-800/40 hover:text-slate-300'
              }`}
              style={armyIdx === i ? { background: a.accent + '18', borderLeft: `3px solid ${a.accent}` } : { borderLeft: '3px solid transparent' }}>
              <span className="mr-1.5">{a.icon}</span>{a.name}
            </button>
          ))}
          <div className="border-t border-slate-800/40 mt-2 pt-2">
            <div className="text-[10px] text-slate-600 uppercase tracking-widest mb-1 px-2 font-bold">Campo</div>
            {SAMPLE_FIELDS.map((f, i) => (
              <button key={i}
                onClick={() => { setFieldIdx(i); trigger(armyIdx, i); }}
                className={`w-full text-left px-2.5 py-1 rounded text-xs transition-all ${
                  fieldIdx === i ? 'text-white font-bold' : 'text-slate-600 hover:text-slate-400'
                }`}
                style={fieldIdx === i ? { background: army.accent + '15' } : {}}>
                {f.icon} {f.name}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 flex flex-col min-h-0">
          <div className="flex-1 relative bg-black overflow-hidden">
            {animating && Anim && (
              <Anim key={animKey} army={army} field={field} onComplete={onComplete} isSkippable={skippable} />
            )}
            {revealed && !animating && (
              <div className="absolute inset-0">
                <Img src={army.image} />
                <Overlay field={field} army={army} visible={true} />
              </div>
            )}
            {!animating && !revealed && (
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-slate-700 text-sm">{army.icon} Seleziona un'armata</span>
              </div>
            )}
          </div>
          <div className="bg-black/40 border-t border-slate-800/40 px-5 py-2 flex items-center justify-between flex-shrink-0">
            <div className="flex items-center gap-2">
              <span>{army.icon}</span>
              <span className="text-xs font-bold" style={{ color: army.accent }}>{army.name}</span>
            </div>
            <div className="flex gap-2">
              <button onClick={() => trigger()} disabled={animating}
                className="px-3 py-1.5 text-xs rounded-lg bg-slate-800 text-slate-400 hover:bg-slate-700 disabled:opacity-30 transition-all">
                🔄 Replay
              </button>
              <button onClick={() => { const n = (armyIdx + 1) % ARMIES.length; setArmyIdx(n); trigger(n, fieldIdx); }} disabled={animating}
                className="px-4 py-1.5 text-xs font-bold rounded-lg bg-gradient-to-r from-amber-600 to-amber-500 text-white hover:from-amber-500 hover:to-amber-400 disabled:opacity-30 transition-all">
                ⚔️ Prossima
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
